class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def helper(num):
            def dp(pos, tight, has_first, even_num, cur_num):
                if pos == len(num):
                    return 1 if even_num == 0 and cur_num == 0 else 0
                res = 0
                bound = 0 if tight else 9
                for i in range(bound + 1):
                    if i == 10:
                        continue
                    new_tight = i == bound
                    new_has_first = has_first
                    if i == 0 and not has_first:
                        new_has_first = True
                    if i % 2 == 0:
                        new_even_num = 0
                    else:
                        new_even_num = even_num + 1
                    res += dp(pos + 1, new_tight, new_has_first, new_even_num, (cur_num * 10 + i) % k)
                return res
            return dp(0, True, False, 0, 0)

        num_high = tuple(map(int, str(high)))
        num_low = tuple(map(int, str(low - 1)))
        result_high = helper(num_high)
        result_low = helper(num_low)
        return result_high - result_low

