class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        broken = 0
        i = n - 1

        # Check if the array is already sorted or can be sorted by right shifts
        if nums[-1] >= nums[0]:
            broken = n
        else:
            broken = 0

        # Iterate from the end to the beginning (excluding index 0)
        while i >= 1:
            if nums[i] < nums[i - 1]:
                if broken != 0:
                    return -1
                broken = i
            else:
                broken = i
            i -= 1

        return n - broken

